#'     parents = ~parents,
#'     values = ~values,
#'     marker = go_treemap_marker(pad = go_treemap_marker_pad())
#'   )
go_treemap_marker_pad <- function(
    ..., b = NULL, l = NULL, r = NULL, t = NULL, skip_invalid = FALSE
