}

#' Treemap tiling objects
#'
#' The object for the \code{tiling} of a treemap trace
#' (\code{\link{go_treemap}()}). \code{go_treemap_tiling()} creates one,
#' with exactly its properties; a named list with the same properties works
#' too.
#'
#' @details
#' Nested objects are named lists, or objects of the constructors their
#' arguments name. Every property is checked against the plotly.js schema
#' when the object is created or modified. A property may be a one-sided
#' formula (\code{color = ~col}): it is kept, and evaluated in the data
#' (then checked) when its trace is added to a figure with
#' \code{add_<trace>()} or \code{add_trace()}.
#'
#' @param flip Determines if the positions obtained from solver are flipped
#'   on each axis. Any combination of \code{"x"}, \code{"y"} joined with
#'   \code{"+"}.
#' @param packing Determines d3 treemap solver. For more info please refer
#'   to https://github.com/d3/d3-hierarchy#treemap-tiling One of
#'   \code{"squarify"}, \code{"binary"}, \code{"dice"}, \code{"slice"},
#'   \code{"slice-dice"}, \code{"dice-slice"}.
#' @param pad Sets the inner padding (in px). Number in the interval [0,
#'   Inf].
#' @param squarifyratio When using "squarify" `packing` algorithm,
#'   according to
#'   https://github.com/d3/d3-hierarchy/blob/v3.1.1/README.md#squarify_ratio
#'   this option specifies the desired aspect ratio of the generated
#'   rectangles. The ratio must be specified as a number greater than or
#'   equal to one. Note that the orientation of the generated rectangles
#'   (tall or wide) is not implied by the ratio; for example, a ratio of
#'   two will attempt to produce a mixture of rectangles whose width:height
#'   ratio is either 2:1 or 1:2. When using "squarify", unlike d3 which
#'   uses the Golden Ratio i.e. 1.618034, Plotly applies 1 to increase
#'   squares in treemap layouts. Number in the interval [1, Inf].
#' @param ... Not for properties, which must be named in full: an
#'   abbreviated or unknown name is an error that suggests the right one.
#' @param skip_invalid If \code{TRUE}, silently drop invalid properties
#'   instead of raising an error.
#' @return A \code{go_treemap_tiling} object (a named list).
#'
#' @concept trace objects
#' @noMd
#' @export
#' @examples
#' cyl <- table(paste(mtcars$cyl, "cylinders"))
#' d <- data.frame(
#'   labels = c("all cars", names(cyl)),
#'   parents = c("", rep("all cars", length(cyl))),
#'   values = c(0, as.vector(cyl))
#' )
#' d |>
#'   go_figure() |>
#'   add_treemap(
#'     labels = ~labels,
#'     parents = ~parents,
#'     values = ~values,
#'     tiling = go_treemap_tiling()
#'   )
go_treemap_tiling <- function(
    ..., flip = NULL, packing = NULL, pad = NULL, squarifyratio = NULL,
    skip_invalid = FALSE
) {
  plotly_object("treemap.tiling", NULL, environment(), list(...), skip_invalid)
}

